**DELIVERY WINDOW LOGIC (CRITICAL):**
You must determine the "D/L" (Delivery) entry based on this logic:
1. **Specific/Promised:** If a specific date or window was discussed/promised, write that.
2. **Flexible:** If the customer stated they are flexible, write "Flexible".
3. **Not Discussed (Default Rules):**
   - If the move is **Between AB and BC** (Origin/Dest is AB/BC): Write "2-7 days (Standard)".
   - If the move involves **Ontario (ON)** (Origin is ON or Destination is ON): Write "1-3 weeks (Standard)".
   - Otherwise: Write "Standard Window".

**Output Format:**
Return a SINGLE Markdown document. 
IMPORTANT: Do NOT use asterisks (*) or markdown bolding (**). That looks ugly in the system. 
Use '## ' for section headers.
Use plain text for keys.

## Operational Briefing
(Use a bulleted list)
- P/U: [Date/Time]
- D/L: [Apply Delivery Window Logic above.]
- Logistics:
  - [Bullet points of EXCEPTIONS, WARNINGS, and SPECIALTY ITEMS only.]
  - [e.g., - Warning: 3rd floor, no elevator.]
  - [e.g., - Heavy: Gun safe (500lbs) in basement.]
  - [e.g., - Fragile: Glass display cabinet - needs packing.]
  - [If none, write "Standard Residential Move".]

## Action Items
- [Tasks for office/crew.]
- [e.g., - Send COI to building.]

## Customer Pain Points
- [Specific worries only.]

## Call Summary
[1 sentence TL;DR.]

## Sentiment Analysis
[Positive/Neutral/Negative - Reason]

## CALENDAR TITLE DETAILS
- Customer First Name: [Name or (N/A)]
- Estimated Weight for Calendar: [e.g., 2.5K or 1500 lbs. Use 'K' for thousands.]
- Pickup Location for Calendar (City, Province/State Abbreviation): [City, 2-letter PROV Abbrev or (N/A). e.g. BRAMPTON, ON]
- Delivery Location for Calendar (City, Province/State Abbreviation): [City, 2-letter PROV Abbrev or (N/A). e.g. EDMONTON, AB]
- Tentative Move Date: [YYYY-MM-DD. The latest discussed move date. Assume current year is 2026. Infer year if missing. If no date found, write (N/A).]
## CALENDAR TITLE DETAILS END
`;

export const generateNotesFromFiles = async (
  files: File[]
): Promise<string> => {
  if (!files || files.length === 0) {
    throw new Error("No files provided for note generation.");
  }
  const localAi = getAiClient();
  try {
    const parts: Part[] = [];
    const fileNames: string[] = files.map(file => file.name);

    for (const file of files) {
      const fileName = file.name.toLowerCase();

      if (file.type.startsWith('audio/')) {
        const base64Audio = await fileToBase64(file);
        const audioMimeType = file.type || 'audio/webm';
        parts.push({ inlineData: { mimeType: audioMimeType, data: base64Audio } });

      } else if (file.type === 'application/pdf' || fileName.endsWith('.pdf')) {
        // PDF is supported as inlineData by Gemini
        const base64Data = await fileToBase64(file);
        parts.push({ inlineData: { mimeType: 'application/pdf', data: base64Data } });

      } else if (file.type.includes('wordprocessingml') || fileName.endsWith('.docx')) {
        // DOCX is NOT supported as inlineData. Must extract text.
        try {
            const docText = await readDocxFile(file);
            parts.push({ text: `\n\n--- START CONTENT FROM WORD DOCUMENT (${fileName}) ---\n${docText}\n--- END CONTENT ---\n\n` });
        } catch (e) {
            console.warn(`Failed to read docx ${fileName}, skipping.`, e);
        }

      } else if (file.type.startsWith('text/') || fileName.endsWith('.md') || fileName.endsWith('.txt')) {
        const textContent = await readTextFile(file);
        parts.push({ text: `\n\n--- START CONTENT FROM FILE: ${file.name} ---\n${textContent}\n--- END CONTENT ---\n\n` });

      } else {
        // Fallback for unknown types - try as text if it's small
        if (file.size < 1024 * 1024) { // 1MB
           try {
               const textContent = await readTextFile(file);
               parts.push({ text: `\n\n--- START CONTENT FROM UNKNOWN FILE: ${file.name} ---\n${textContent}\n--- END CONTENT ---\n\n` });
           } catch (e) {
               console.warn(`Could not read file ${fileName} as text.`);
           }
        }
      }
    }

    if (parts.length === 0) {
        throw new Error("No valid content could be extracted from the provided files.");
    }

    const userPrompt = `Analyze these files (${fileNames.join(', ')}) and generate the Operational Briefing. Ensure you read any meeting notes from the provided documents.`;
    parts.push({ text: userPrompt });

    const response: GenerateContentResponse = await localAi.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: { parts },
      config: {
        systemInstruction: BASE_INSTRUCTION,
      },
    });

    const generatedText = response.text;
    if (!generatedText || generatedText.trim() === "") {
      console.warn("Gemini API returned an empty text response for notes generation.");
      throw new Error("The AI was unable to generate notes. Please check the input files.");
    }
    return generatedText;

  } catch (error: unknown) {
    console.error("Error with Gemini API (Notes):", error);
    if (error instanceof Error) {
        if (error.message.includes("API key")) throw new Error("Invalid Gemini API Key.");
        if (error.message.includes("SAFETY")) throw new Error("Content blocked by safety settings.");
        throw new Error(`AI processing failed: ${error.message}`);
    }
    throw new Error("An unknown error occurred while communicating with the AI service.");
  }
};


export const generateSpecificInfoFromFiles = async (
  initialFiles: File[],
  userQuery: string
): Promise<string> => {
  if (!initialFiles || initialFiles.length === 0) {
      throw new Error("No initial files provided for specific query.");
  }
  const localAi = getAiClient();
  try {
    const parts: Part[] = [];
    for (const file of initialFiles) {
        const fileName = file.name.toLowerCase();

        if (file.type.startsWith('audio/')) {
            const base64Audio = await fileToBase64(file);
            const audioMimeType = file.type || 'audio/webm';
            parts.push({ inlineData: { mimeType: audioMimeType, data: base64Audio } });

        } else if (file.type === 'application/pdf' || fileName.endsWith('.pdf')) {
             const base64Data = await fileToBase64(file);
             parts.push({ inlineData: { mimeType: 'application/pdf', data: base64Data } });

        } else if (file.type.includes('wordprocessingml') || fileName.endsWith('.docx')) {
             try {
                const docText = await readDocxFile(file);
                parts.push({ text: `\n\n--- START CONTENT FROM WORD DOCUMENT (${fileName}) ---\n${docText}\n--- END CONTENT ---\n\n` });
             } catch (e) {
                 console.warn(`Failed to read docx ${fileName} for query.`, e);
             }

        } else if (file.type.startsWith('text/') || fileName.endsWith('.md') || fileName.endsWith('.txt')) {
            const textContent = await readTextFile(file);
            parts.push({ text: `\n\n--- START CONTENT FROM FILE: ${file.name} ---\n${textContent}\n--- END CONTENT ---\n\n` });
        }
    }

    if (parts.length === 0) {
        return "No readable content found in files.";
    }

    const systemInstruction = `You are an AI assistant for a moving company. Answer the user's question based on the provided files (audio, text, Word docs, or PDFs). Be concise. If the answer isn't there, say "Not found in files."`;

    const userPrompt = `User's Question: "${userQuery}"\n\nProvide your answer based on the file analysis:`;
    parts.push({ text: userPrompt }); 

    const response: GenerateContentResponse = await localAi.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: { parts }, 
      config: {
        systemInstruction,
      },
    });

    const generatedText = response.text;
     if (!generatedText || generatedText.trim() === "") {
      return "The requested information was not found in the files.";
    }
    return generatedText;

  } catch (error: unknown) {
    console.error("Error with Gemini API (Specific Info):", error);
    if (error instanceof Error) {
       if (error.message.includes("Failed to read file")) return `Error: ${error.message}`;
       return `Error: ${error.message}`;
    }
    return "An unknown error occurred.";
  }
};

