            <div className="p-4 pt-0 text-text-main text-sm leading-relaxed">
                {children}
            </div>
          </div>
      </div>
    </div>
  );
};

export const NoteDisplay: React.FC<NoteDisplayProps> = ({ notes, editedNotes, onNotesChange, onToast }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [quoteNumber, setQuoteNumber] = useState("");

  const titleRaw = getCalendarTitle(editedNotes, quoteNumber);
  const weight = formatWeight(extractCalendarDetail(editedNotes, "Estimated Weight for Calendar"));
  const puLoc = formatLocation(extractCalendarDetail(editedNotes, "Pickup Location for Calendar (City, Province/State Abbreviation)"), "TBD");
  const dlLoc = formatLocation(extractCalendarDetail(editedNotes, "Delivery Location for Calendar (City, Province/State Abbreviation)"), "TBD");
  const customerName = extractCalendarDetail(editedNotes, "Customer First Name", "Unknown");

  // Sentiment (Handles clean ## header or legacy **)
  const sentimentSection = editedNotes.match(/(?:##|\*\*)\s*Sentiment Analysis(?:\s*\(Overall\))?:?\s*(.*)/i);
  const sentimentText = sentimentSection ? sentimentSection[1].toLowerCase() : "";
  const isNegative = sentimentText.includes("negative") || sentimentText.includes("concerned") || sentimentText.includes("worried");
  const isPositive = sentimentText.includes("positive") || sentimentText.includes("relieved");

  // --- Render Logic ---
  const formattedContent = (content: string, isChecklist = false) => {
    return content.split('\n').map((line, index) => {
      if (!line.trim()) return null;

      const lowerLine = line.toLowerCase();
      const isImportant = lowerLine.includes("fragile") || lowerLine.includes("urgent") || lowerLine.includes("warning") || lowerLine.includes("promise");
      const isCritical = lowerLine.includes("critical");

      // Clean line of markdown asterisks for display
      const cleanLine = line.replace(/^\s*-\s*/, '').replace(/\*\*/g, '');

      if (line.trim().startsWith('- ')) {
        if (isChecklist) {
            return (
                <div key={index} className={`flex items-start mb-2 p-2 rounded-lg transition-colors hover:bg-white/40 ${isImportant ? 'bg-red-50/50' : ''}`}>
                    <input type="checkbox" className="mt-1 mr-3 h-4 w-4 rounded border-gray-300 text-accent-primary focus:ring-accent-primary cursor-pointer" />
                    <span className={isImportant ? 'font-medium text-red-800' : 'text-gray-700'}>{cleanLine}</span>
                </div>
            );
        }

        // Smart Bolding for Key: Value pairs
        const keyMatch = cleanLine.match(/^([^:]+):\s*(.*)$/);

        return (
            <li key={index} className={`mb-1 pl-2 border-l-2 ${isImportant ? 'border-red-400 bg-red-50/30' : 'border-gray-300'} py-1`}>
                {keyMatch ? (
                     <span className="text-gray-800">
                        <strong className={`font-bold ${isCritical ? 'text-red-600 uppercase' : 'text-gray-900'}`}>{keyMatch[1]}:</strong> {keyMatch[2]}
                     </span>
                ) : (
                    <span dangerouslySetInnerHTML={{ __html: cleanLine }} />
                )}
            </li>
        );
      }

      return <p key={index} className="my-1 text-gray-800" dangerouslySetInnerHTML={{ __html: cleanLine }} />;
    });
  };

  const handleCopy = (text: string, label: string) => {
    if (!text.trim()) return;
    navigator.clipboard.writeText(text).then(() => {
      onToast(`${label} copied!`);
    }).catch(err => console.error('Failed to copy: ', err));
  };

  const handleCreateCalendarEvent = () => {
    const details = getOperationalBriefing(editedNotes);
    const pickupLocationRaw = extractCalendarDetail(editedNotes, "Pickup Location for Calendar (City, Province/State Abbreviation)", "");
    const moveDateRaw = extractCalendarDetail(editedNotes, "Tentative Move Date", "N/A");

    let locationParam = "";
    // Clean location param
    const cleanPickup = pickupLocationRaw.replace(/\*\*/g, '');
    if (cleanPickup && !cleanPickup.includes("N/A")) {
         locationParam = `&location=${encodeURIComponent(cleanPickup)}`;
    }

    let datesParam = "";
    const dateRegex = /(\d{4})-(\d{2})-(\d{2})/;
    const match = moveDateRaw.match(dateRegex);

    if (match) {
        // Enforce 2026 year for all calendar events
        const year = 2026;
        const month = parseInt(match[2], 10) - 1;
        const day = parseInt(match[3], 10);

        const startDate = new Date(year, month, day);
        const endDate = new Date(year, month, day);
        endDate.setDate(endDate.getDate() + 1); 

        const formatDate = (d: Date) => {
            const y = d.getFullYear();
            const m = String(d.getMonth() + 1).padStart(2, '0');
            const dt = String(d.getDate()).padStart(2, '0');
            return `${y}${m}${dt}`;
        }

        datesParam = `&dates=${formatDate(startDate)}/${formatDate(endDate)}`;
    }

    const calendarUrl = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(titleRaw)}&details=${encodeURIComponent(details)}${locationParam}${datesParam}`;
    window.open(calendarUrl, '_blank', 'noopener,noreferrer');
    onToast("Opening Google Calendar...");
  };

  // Split by "## " or legacy "**" 
  const sections = editedNotes.split(/\n(?=## |(?:\*\*(?!.*End\*\*)))/g).filter(s => s.trim() !== '').map(section => {
    // Clean title extraction for ## and **
    let title = 'Note';
    let content = section;

    if (section.trim().startsWith('##')) {
        const firstLineEnd = section.indexOf('\n');
        if (firstLineEnd !== -1) {
            title = section.substring(0, firstLineEnd).replace(/##\s*/, '').trim();
            content = section.substring(firstLineEnd).trim();
        } else {
            title = section.replace(/##\s*/, '').trim();
            content = "";
        }
    } else {
        const match = section.match(/\*\*(.*?)\*\*/);
        if (match) {
             title = match[1].replace(':', '');
             content = section.replace(/\*\*(.*?)\*\*\n?/, '').trim();
        }
    }

    return { title, content };
  });

  return (
    <div className="w-full h-full flex flex-col">

      {/* --- Header / Toolbar --- */}
      <div className="flex justify-between items-center mb-6 px-1">
        <div className="flex items-center space-x-3">
             <div className={`w-2 h-12 rounded-full ${isNegative ? 'bg-red-500 shadow-[0_0_10px_red]' : isPositive ? 'bg-green-500 shadow-[0_0_10px_lime]' : 'bg-accent-primary shadow-[0_0_10px_cyan]'}`}></div>
             <div>
                 <h2 className="text-2xl font-bold text-text-main tracking-tight">Mission Control</h2>
                 <p className="text-xs text-text-muted font-medium">MOVER TECHNICAL SYNTHESIS SYSTEM</p>
             </div>
        </div>
        <div className="flex items-center space-x-2 bg-white/30 p-1.5 rounded-xl border border-white/40 shadow-sm">
            <input
                type="text"
                placeholder="Quote #"
                value={quoteNumber}
                onChange={(e) => setQuoteNumber(e.target.value)}
                className="w-28 p-2 text-sm bg-white/40 border border-white/40 rounded-lg text-text-main placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-accent-primary/50 text-center font-medium placeholder:text-xs"
            />
            <div className="w-px h-6 bg-gray-300/50 mx-1"></div>
            <button onClick={() => { setIsEditing(!isEditing); if (isEditing) onNotesChange(editedNotes); }} className="p-2 rounded-lg text-text-muted hover:text-accent-primary hover:bg-white transition-all" title={isEditing ? 'Save' : 'Edit'}>
                {isEditing ? <CheckIcon className="w-5 h-5 text-green-600"/> : <PencilIcon className="w-5 h-5"/>}
            </button>
            <div className="w-px h-6 bg-gray-300/50 mx-1"></div>
            <button onClick={handleCreateCalendarEvent} className="p-2 rounded-lg text-text-muted hover:text-blue-600 hover:bg-blue-50 transition-all" title="Create Event">
                <CalendarPlusIcon className="w-5 h-5" />
            </button>
            <button onClick={() => handleCopy(titleRaw, 'Calendar Title')} className="p-2 rounded-lg text-text-muted hover:text-purple-600 hover:bg-purple-50 transition-all" title="Copy Title">
                <CalendarDaysIcon className="w-5 h-5" />
            </button>
            <button onClick={() => handleCopy(editedNotes, 'Full Notes')} className="p-2 rounded-lg text-text-muted hover:text-green-600 hover:bg-green-50 transition-all" title="Copy Body">
                <ClipboardIcon className="w-5 h-5" />
            </button>
        </div>
      </div>

      {/* --- Quick Stats Grid --- */}
      {!isEditing && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
           <DataCard label="Customer" value={customerName} />
           <DataCard label="Est. Weight" value={weight} highlight={weight !== "N/A"} />
           <DataCard label="Origin" value={puLoc} />
           <DataCard label="Destination" value={dlLoc} />
        </div>
      )}

      {/* --- Main Content Area --- */}
      {isEditing ? (
        <textarea
          value={editedNotes}
          onChange={(e) => onNotesChange(e.target.value)}
          className="w-full flex-grow p-6 font-mono text-sm bg-white/60 border border-white/60 rounded-xl shadow-inner focus:ring-2 focus:ring-accent-primary/50 focus:border-accent-primary outline-none resize-none backdrop-blur-md"
        />
      ) : (
        <div className="flex-grow overflow-y-auto pr-2 space-y-1 pb-10">
          {sections.map((section, index) => {
             if (section.title.toUpperCase().includes("CALENDAR TITLE")) return null;

             const isChecklist = section.title.includes("Action Items") || section.title.includes("Next Steps");
             const isRisks = section.title.includes("Pain Points") || section.title.includes("Concerns");
             const sentiment = isRisks ? 'negative' : (section.title.includes("Briefing") ? 'neutral' : undefined);

             return (
                <AccordionSection key={index} title={section.title} sentiment={sentiment} defaultOpen={!section.title.includes("Sentiment")}>
                    {isChecklist ? (
                        <div className="flex flex-col">
                            {formattedContent(section.content, true)}
                        </div>
                    ) : (
                        <ul className="space-y-1">
                            {formattedContent(section.content)}
                        </ul>
                    )}
                </AccordionSection>
             )
          })}
        </div>
      )}
    </div>
  );
};
